#include <string>
#include <unordered_map>
using namespace std;

class Solution {
public:
    bool areOccurrencesEqual(string s) {
        unordered_map<char, int> count;
        for (char c : s) count[c]++;
        int val = count[s[0]];
        for (auto& [k, v] : count)
            if (v != val) return false;
        return true;
    }
};
